class Profile {
  Profile({this.email});

  final String? email; // null until the user verifies it
}

String greeting(Profile profile) {
  final email = profile.email; // a local copy, so the null check promotes it
  if (email == null) return 'Signed in (email not verified)';
  return 'Signed in as $email';
}

void main() {
  print(greeting(Profile(email: 'sara@example.com')));
  print(greeting(Profile())); // Signed in (email not verified)
}

